-- Cardoso Marketing Hub — Social: seed do plano de mídias (0076 antes). Idempotente.
-- Gerado a partir de Planejamento_Midias_Digitais_Cardoso.html (614 peças + 40 prazos).
-- Reexecutar atualiza os campos de conteúdo pelo ext_id, preservando aprovação/comentários.

set lock_timeout = '5s';

on conflict (ext_id) do update set
  pub_date=excluded.pub_date,
  weekday=excluded.weekday,
  month_label=excluded.month_label,
  week_theme=excluded.week_theme,
  brand=excluded.brand,
  network=excluded.network,
  channel=excluded.channel,
  piece_type=excluded.piece_type,
  format=excluded.format,
  origin=excluded.origin,
  pauta=excluded.pauta,
  product=excluded.product,
  sku=excluded.sku,
  objective=excluded.objective,
  cta=excluded.cta,
  media_use=excluded.media_use;

on conflict (ext_key) do update set
  marco=excluded.marco, dm=excluded.dm, limite=excluded.limite, acao=excluded.acao, resp=excluded.resp, ord=excluded.ord;
